update public.programming_modules
set description='ابدأ ببناء صفحات ويب حقيقية: افهم المتصفح وHTML، نسّق الصفحات باستخدام CSS، ثم أضف التفاعل باستخدام JavaScript.',updated_at=now()
where id='web-foundations';
insert into public.programming_lessons(id,module_id,title,summary,content_md,duration_minutes,sort_order,published) values
('web-01-how-web-works','web-foundations','كيف يعمل الويب؟','افهم دور المتصفح والصفحة والخادم والملفات الأساسية للموقع.',
E'## ما الذي يحدث عندما تفتح موقعًا؟\nالمتصفح يطلب ملفات الموقع من خادم، ثم يقرأها ويعرض الصفحة. في البداية ركّز على ثلاثة أجزاء:\n\n- **HTML** يحدد محتوى الصفحة وهيكلها.\n- **CSS** يحدد الألوان والمسافات والتنسيق.\n- **JavaScript** يضيف التفاعل والسلوك.\n\n## ملفات المشروع\nيمكن أن يبدأ مشروع بسيط بهذه الملفات:\n\n```text\nmy-first-site/\n  index.html\n  style.css\n  script.js\n```\n\n## دور كل ملف\nملف index.html هو صفحة البداية، وstyle.css للتصميم، وscript.js للتفاعل.\n\n## تدريب\nأنشئ مجلدًا لمشروعك، ثم أنشئ داخله الملفات الثلاثة. اكتب بجانب كل ملف وظيفته في ملاحظة قصيرة.',12,1,true),
('web-02-html-document','web-foundations','بناء أول صفحة HTML','اكتب الهيكل الأساسي الصحيح لأي صفحة HTML.',
E'## الهيكل الأساسي\nكل صفحة HTML تبدأ بتعريف نوع المستند، ثم عنصر html الذي يحتوي على head وbody.\n\n```html\n<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>صفحتي الأولى</title>\n</head>\n<body>\n  <h1>مرحبًا بعالمي</h1>\n  <p>هذه أول صفحة أبنيها.</p>\n</body>\n</html>\n```\n\n## شرح الأجزاء\n- head يحتوي معلومات الصفحة التي لا تظهر عادةً كمحتوى رئيسي.\n- title يحدد عنوان علامة التبويب.\n- body يحتوي المحتوى الذي يراه الزائر.\n- viewport يساعد على عرض الصفحة بشكل مناسب على الهاتف.\n\n## تدريب\nأنشئ صفحة باسمك، واكتب عنوانًا رئيسيًا وفقرة قصيرة، ثم افتح الملف في المتصفح.',15,2,true),
('web-03-html-content','web-foundations','العناوين والفقرات والعناصر الدلالية','نظّم المحتوى بعناصر HTML الصحيحة واجعل الصفحة سهلة الفهم.',
E'## العناوين والفقرات\nاستخدم h1 للعنوان الرئيسي، ثم h2 وh3 للعناوين الفرعية، واستخدم p للفقرات.\n\n```html\n<main>\n  <h1>رحلتي في تعلم البرمجة</h1>\n  <section>\n    <h2>هدفي</h2>\n    <p>أتعلم بناء صفحات ويب مفيدة.</p>\n  </section>\n  <footer>تم إنشاء الصفحة للتدريب.</footer>\n</main>\n```\n\n## عناصر دلالية\nheader للمقدمة، وnav للروابط الرئيسية، وmain للمحتوى الأساسي، وsection لقسم موضوعي، وfooter للتذييل.\n\n## لماذا نهتم؟\nالهيكل الدلالي يسهل قراءة الصفحة وصيانتها ويساعد التقنيات المساعدة ومحركات البحث على فهم أقسامها.\n\n## تدريب\nأنشئ صفحة تعريفية بها header وmain وقسمان section وfooter. استخدم عنوانًا رئيسيًا واحدًا واضحًا.',15,3,true),
('web-04-links-images-lists','web-foundations','الروابط والصور والقوائم','أضف روابط وصورًا وقوائم مع وصف مناسب للمحتوى.',
E'## الروابط\nاستخدم العنصر a مع href لتحديد الوجهة:\n\n```html\n<a href="https://example.com">زيارة موقع تجريبي</a>\n```\n\n## الصور\nاستخدم img، واكتب وصفًا بديلًا مفيدًا في alt:\n\n```html\n<img src="images/book.jpg" alt="كتاب مفتوح على مكتب">\n```\n\n## القوائم\nالقائمة غير المرتبة تستخدم ul، والمرتبة تستخدم ol، وكل عنصر داخلها يستخدم li.\n\n```html\n<h2>أهدافي</h2>\n<ul>\n  <li>تعلم HTML</li>\n  <li>تطبيق CSS</li>\n  <li>إضافة JavaScript</li>\n</ul>\n```\n\n## تذكّر\nلا تستخدم نصًا عامًا مثل صورة في alt إذا كانت الصورة تحمل معنى؛ اكتب وصفًا مختصرًا يوضح وظيفتها.\n\n## تدريب\nأنشئ صفحة لهواية تحبها، وأضف رابطًا مفيدًا وصورة مناسبة وقائمة بثلاثة أشياء مرتبطة بالهواية.',16,4,true),
('web-05-css-first-style','web-foundations','ربط CSS وتنسيق الصفحة','اربط ملف CSS بصفحة HTML واستخدم المحددات والخصائص الأساسية.',
E'## ربط ملف CSS\nضع هذا السطر داخل head:\n\n```html\n<link rel="stylesheet" href="style.css">\n```\n\n## أول تنسيقات\n```css\nbody {\n  font-family: Arial, sans-serif;\n  background: #f4f1f8;\n  color: #241b2f;\n}\n\nh1 {\n  color: #7041a6;\n  text-align: center;\n}\n```\n\n## المحددات Selectors\n- p يختار كل عناصر الفقرة.\n- .card يختار العناصر التي تحمل class باسم card.\n- #main-title يختار العنصر الذي يحمل id بهذا الاسم.\n\n## تدريب\nأضف class باسم highlight إلى فقرة، ثم اكتب قاعدة CSS تغير لون النص والخلفية والمسافة الداخلية لها.',16,5,true),
('web-06-box-model-layout','web-foundations','المسافات ونموذج الصندوق','افهم margin وpadding وborder وابدأ تنظيم العناصر باستخدام Flexbox.',
E'## نموذج الصندوق Box Model\nكل عنصر يمكن التفكير فيه كصندوق يتكون من المحتوى، ثم padding، ثم border، ثم margin.\n\n```css\n.card {\n  width: 280px;\n  padding: 20px;\n  border: 1px solid #c8b7d8;\n  margin: 16px;\n  box-sizing: border-box;\n  border-radius: 14px;\n}\n```\n\n## Flexbox\nيستخدم Flexbox لترتيب العناصر داخل مساحة واحدة:\n\n```css\n.cards {\n  display: flex;\n  gap: 16px;\n  flex-wrap: wrap;\n  justify-content: center;\n}\n```\n\n## تصميم متجاوب\nاستخدم media query لتغيير التخطيط عندما تصبح الشاشة ضيقة:\n\n```css\n@media (max-width: 600px) {\n  .cards {\n    flex-direction: column;\n  }\n}\n```\n\n## تدريب\nأنشئ ثلاث بطاقات داخل حاوية Flexbox، واجعلها تظهر بجانب بعضها على الشاشة الواسعة وتحت بعضها على الهاتف.',18,6,true),
('web-07-javascript-basics','web-foundations','مقدمة JavaScript والمتغيرات','أضف ملف JavaScript وتعلم المتغيرات والقيم والدوال البسيطة.',
E'## ربط JavaScript\nضع script قبل إغلاق body أو استخدم defer في head:\n\n```html\n<script src="script.js" defer></script>\n```\n\n## المتغيرات\nاستخدم const للقيمة التي لن تعيد إسنادها، وlet عندما تحتاج إلى تغيير القيمة:\n\n```javascript\nconst courseName = "Web Development";\nlet completedLessons = 0;\ncompletedLessons = completedLessons + 1;\n\nconsole.log(courseName);\nconsole.log(completedLessons);\n```\n\n## الدوال\n```javascript\nfunction welcomeStudent(name) {\n  return "Welcome, " + name;\n}\n\nconsole.log(welcomeStudent("Mona"));\n```\n\n## تدريب\nأنشئ متغيرًا لاسم مشروعك وآخر لعدد صفحاته، ثم اكتب دالة تعيد رسالة ترحيب باسم المشروع.',18,7,true),
('web-08-dom-events','web-foundations','التعامل مع الصفحة والأحداث DOM','غيّر محتوى الصفحة استجابةً لنقر المستخدم على زر.',
E'## ما DOM؟\nDOM تمثيل للصفحة يستطيع JavaScript من خلاله الوصول إلى العناصر وتعديلها.\n\n## اختيار عنصر وتغيير محتواه\n```html\n<h1 id="message">مرحبًا!</h1>\n<button id="changeButton" type="button">غيّر الرسالة</button>\n```\n\n```javascript\nconst message = document.querySelector("#message");\nconst button = document.querySelector("#changeButton");\n\nbutton.addEventListener("click", function () {\n  message.textContent = "أحسنت! هذا أول تفاعل لك.";\n});\n```\n\n## ماذا يحدث؟\n- querySelector يختار عنصرًا باستخدام محدد CSS.\n- addEventListener يستمع إلى حدث مثل click.\n- textContent يغير النص الظاهر داخل العنصر.\n\n## مشروع صغير\nأنشئ بطاقة تعريف فيها عنوان وفقرة وزر. عند الضغط على الزر، غيّر نص الفقرة. جرّب إضافة زر ثانٍ يعيد النص الأصلي.',20,8,true)
on conflict(id) do nothing;